## Problem 6 — spans

Edit `ex6/solution.ts`. Implement:

```ts
export interface Span {
  name: string;
  spanId: string;
  parentSpanId?: string;
  startMs: number;
  endMs?: number;
  attributes: Record<string, unknown>;
  status: "unset" | "ok" | "error";
  events: Array<{ name: string; timeMs: number }>;
}

export interface Tracer {
  startSpan(name: string, attributes?: Record<string, unknown>): {
    setAttribute(key: string, value: unknown): void;
    addEvent(name: string): void;
    recordError(error: Error): void;
    end(): void;
  };
  withSpan<T>(name: string, fn: () => T): T;
  finished(): Span[];
}

export function createTracer(deps: { now: () => number; nextId: () => string }): Tracer
```

Requirements:

- a span started while another is active gets it as its parent, and nesting is
  restored correctly when the inner one ends — including when it ends out of
  order;
- `withSpan` starts a span, runs `fn`, ends the span in a `finally`, and marks
  the span `"error"` with the error recorded when `fn` throws (then rethrows);
- `end()` twice is a no-op;
- `finished()` returns ended spans in the order they ended.

```ts
const tracer = createTracer({ now, nextId });
tracer.withSpan("handler", () => tracer.withSpan("db.query", () => 42));
tracer.finished().map((s) => s.name);         // ["db.query", "handler"]
tracer.finished()[0].parentSpanId === tracer.finished()[1].spanId;   // true
```

