// v3nc06_observability / ex6 - reference solution (author only, used by `dojo verify`).

export interface Span {
  name: string;
  spanId: string;
  parentSpanId?: string;
  startMs: number;
  endMs?: number;
  attributes: Record<string, unknown>;
  status: "unset" | "ok" | "error";
  events: Array<{ name: string; timeMs: number }>;
}

export interface Tracer {
  startSpan(
    name: string,
    attributes?: Record<string, unknown>,
  ): {
    setAttribute(key: string, value: unknown): void;
    addEvent(name: string): void;
    recordError(error: Error): void;
    end(): void;
  };
  withSpan<T>(name: string, fn: () => T): T;
  finished(): Span[];
}

export function createTracer(deps: { now: () => number; nextId: () => string }): Tracer {
  // A stack is correct for synchronous nesting. Across awaits, this is exactly
  // what AsyncLocalStorage (ex3) exists to replace.
  const stack: Span[] = [];
  const done: Span[] = [];

  function startSpan(name: string, attributes: Record<string, unknown> = {}) {
    const span: Span = {
      name,
      spanId: deps.nextId(),
      parentSpanId: stack.at(-1)?.spanId,
      startMs: deps.now(),
      attributes: { ...attributes },
      status: "unset",
      events: [],
    };
    stack.push(span);

    let ended = false;
    return {
      setAttribute(key: string, value: unknown): void {
        // High cardinality is fine here - a trace is stored per request, not
        // aggregated into series the way a metric is.
        span.attributes[key] = value;
      },
      addEvent(eventName: string): void {
        span.events.push({ name: eventName, timeMs: deps.now() });
      },
      recordError(error: Error): void {
        span.status = "error";
        span.attributes["error.type"] = error.name;
        span.attributes["error.message"] = error.message;
      },
      end(): void {
        if (ended) return;
        ended = true;
        span.endMs = deps.now();
        if (span.status === "unset") span.status = "ok";
        // Remove by identity, not by popping: an out-of-order end would
        // otherwise remove someone else's span and reparent everything after.
        const index = stack.lastIndexOf(span);
        if (index >= 0) stack.splice(index, 1);
        done.push(span);
      },
    };
  }

  return {
    startSpan,

    withSpan<T>(name: string, fn: () => T): T {
      const span = startSpan(name);
      try {
        return fn();
      } catch (error) {
        span.recordError(error as Error);
        // Record and rethrow: swallowing would both hide the failure from the
        // caller and leave the span looking successful.
        throw error;
      } finally {
        span.end();
      }
    },

    finished: () => [...done],
  };
}

