// v3nc06_observability / ex7 - reference solution (author only, used by `dojo verify`).

export interface Registry {
  counter(name: string, labels?: Record<string, string>, by?: number): void;
  gauge(name: string, value: number, labels?: Record<string, string>): void;
  observe(name: string, value: number, labels?: Record<string, string>): void;
  seriesCount(): number;
  droppedSeries(): number;
  expose(): string;
}

interface Histogram {
  counts: number[];
  inf: number;
  sum: number;
  count: number;
}

// Sorted keys, so {a,b} and {b,a} are one series - call sites will not agree
// on label order and should not have to.
function seriesKey(name: string, labels: Record<string, string>): string {
  const rendered = Object.keys(labels)
    .sort()
    .map((key) => `${key}="${labels[key]}"`)
    .join(",");
  return rendered.length > 0 ? `${name}{${rendered}}` : name;
}

export function createRegistry(options: { buckets: readonly number[]; maxSeries: number }): Registry {
  const counters = new Map<string, number>();
  const gauges = new Map<string, number>();
  const histograms = new Map<string, Histogram>();
  let dropped = 0;

  const total = (): number => counters.size + gauges.size + histograms.size;

  // The guard lives in exactly one place: the function that decides whether a
  // series may exist. A bad label then costs one metric, not the monitoring
  // system.
  const admit = (key: string, exists: boolean): boolean => {
    if (exists) return true;
    if (total() >= options.maxSeries) {
      // Counted, not silent: a silent cap is indistinguishable from a broken
      // instrument.
      dropped += 1;
      return false;
    }
    return true;
  };

  return {
    counter(name, labels = {}, by = 1): void {
      const key = seriesKey(name, labels);
      if (!admit(key, counters.has(key))) return;
      counters.set(key, (counters.get(key) ?? 0) + by);
    },

    gauge(name, value, labels = {}): void {
      const key = seriesKey(name, labels);
      if (!admit(key, gauges.has(key))) return;
      gauges.set(key, value);
    },

    observe(name, value, labels = {}): void {
      const key = seriesKey(name, labels);
      if (!admit(key, histograms.has(key))) return;
      let histogram = histograms.get(key);
      if (!histogram) {
        histogram = { counts: options.buckets.map(() => 0), inf: 0, sum: 0, count: 0 };
        histograms.set(key, histogram);
      }
      // Cumulative: every bucket whose bound the value clears. This is what
      // makes histograms addable across instances.
      options.buckets.forEach((bound, index) => {
        if (value <= bound) histogram.counts[index] += 1;
      });
      histogram.inf += 1;
      histogram.sum += value;
      histogram.count += 1;
    },

    seriesCount: total,
    droppedSeries: () => dropped,

    expose(): string {
      const lines: string[] = [];
      for (const [key, value] of counters) lines.push(`${key} ${value}`);
      for (const [key, value] of gauges) lines.push(`${key} ${value}`);

      for (const [key, histogram] of histograms) {
        const [name, labelPart] = key.includes("{")
          ? [key.slice(0, key.indexOf("{")), key.slice(key.indexOf("{") + 1, -1)]
          : [key, ""];
        const withLe = (le: string): string =>
          labelPart.length > 0 ? `{le="${le}",${labelPart}}` : `{le="${le}"}`;
        options.buckets.forEach((bound, index) => {
          lines.push(`${name}_bucket${withLe(String(bound))} ${histogram.counts[index]}`);
        });
        lines.push(`${name}_bucket${withLe("+Inf")} ${histogram.inf}`);
        lines.push(`${name}_sum${labelPart ? `{${labelPart}}` : ""} ${histogram.sum}`);
        lines.push(`${name}_count${labelPart ? `{${labelPart}}` : ""} ${histogram.count}`);
      }

      // Sorted so a scrape is diffable and tests are stable.
      return lines.sort().join("\n");
    },
  };
}

// v3nc06_observability / ex8 - reference solution (author only, used by `dojo verify`).

export interface Bucket {
  le: number;
  count: number;
}

export interface QuantileResult {
  value: number;
  bounded: boolean;
}

export function quantileFromBuckets(buckets: readonly Bucket[], q: number): QuantileResult {
  if (!(q > 0 && q <= 1)) throw new RangeError(`q must be in (0, 1], got ${q}`);
  if (buckets.length === 0) return { value: 0, bounded: false };

  // Cumulative, so the total is simply the last bucket.
  const total = buckets[buckets.length - 1].count;
  if (total === 0) return { value: 0, bounded: false };

  const rank = q * total;
  let previous: Bucket = { le: 0, count: 0 };

  for (const bucket of buckets) {
    if (bucket.count < rank) {
      previous = bucket;
      continue;
    }
    if (!Number.isFinite(bucket.le)) {
      // Nothing to interpolate against. Say so, so the caller can render
      // ">2.5s" rather than a fabricated number.
      return { value: previous.le, bounded: false };
    }
    const inBucket = bucket.count - previous.count;
    if (inBucket <= 0) return { value: bucket.le, bounded: true };
    const position = rank - previous.count;
    // The standard linear assumption: observations spread evenly between the
    // bounds. Latency never does - it clusters low - so this is biased upward
    // inside wide buckets.
    return {
      value: previous.le + ((bucket.le - previous.le) * position) / inBucket,
      bounded: true,
    };
  }

  return { value: previous.le, bounded: false };
}

// The reason histograms are stored as cumulative counters: they add. Ten
// servers' p99s cannot be averaged, but their buckets can be summed and the
// quantile computed from the total.
export function mergeBuckets(sets: ReadonlyArray<readonly Bucket[]>): Bucket[] {
  if (sets.length === 0) return [];
  const bounds = sets[0].map((bucket) => bucket.le);

  for (const set of sets) {
    const same = set.length === bounds.length && set.every((bucket, i) => bucket.le === bounds[i]);
    // Interpolating across mismatched schemes produces numbers with no
    // meaning, so refuse instead.
    if (!same) throw new Error("cannot merge histograms with different bucket boundaries");
  }

  return bounds.map((le, index) => ({
    le,
    count: sets.reduce((sum, set) => sum + set[index].count, 0),
  }));
}

