  metrics: { counter(name: string, labels: Record<string, string>): void; observe(name: string, value: number, labels: Record<string, string>): void };
  tracer: { startSpan(name: string): { setAttribute(k: string, v: unknown): void; recordError(e: Error): void; end(): void } };
  context: { run<T>(ctx: { requestId: string; traceId: string }, fn: () => T): T; current(): { requestId: string; traceId: string } | undefined };
  sampler: (input: { traceId: string; upstreamSampled?: boolean }) => { sampled: boolean };
  now: () => number;
  nextId: () => string;
}

export interface RequestLike { route: string; method: string; headers: Record<string, string | undefined>; }

export function instrument<T>(
  handler: () => Promise<T>,
  request: RequestLike,
  deps: Deps,
): Promise<{ result?: T; status: number; error?: Error }>
```

For every request:

1. parse an inbound `traceparent` (reuse ex4's rules) or mint a new trace id
   and ask the sampler;
2. run the handler inside a context carrying `requestId` and `traceId`;
3. start a span named `` `${method} ${route}` `` — but only when sampled;
4. on success: log one `info` line with route, method, status 200, duration
   and both ids; increment `http_requests_total{route,status}`; observe
   `http_request_duration_seconds{route}` in **seconds**;
5. on failure: log one `error` line with the same fields plus the error name,
   record the error on the span, use status 500, and still emit both metrics;
6. return `{ result, status }` or `{ error, status: 500 }` — `instrument`
   never throws.

Metric labels are `route` and `status` only. Ids go in the log and the span,
never in a label.

