// v3nc06_observability / challenge - reference solution (author only, used by `dojo verify`).

export interface Deps {
  logger: { info(fields: Record<string, unknown>): void; error(fields: Record<string, unknown>): void };
  metrics: {
    counter(name: string, labels: Record<string, string>): void;
    observe(name: string, value: number, labels: Record<string, string>): void;
  };
  tracer: {
    startSpan(name: string): {
      setAttribute(key: string, value: unknown): void;
      recordError(error: Error): void;
      end(): void;
    };
  };
  context: {
    run<T>(ctx: { requestId: string; traceId: string }, fn: () => T): T;
    current(): { requestId: string; traceId: string } | undefined;
  };
  sampler: (input: { traceId: string; upstreamSampled?: boolean }) => { sampled: boolean };
  now: () => number;
  nextId: () => string;
}

export interface RequestLike {
  route: string;
  method: string;
  headers: Record<string, string | undefined>;
}

const TRACEPARENT = /^([0-9a-f]{2})-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/;
const ALL_ZERO = /^0+$/;

// A no-op span keeps the rest of the code free of `if (span)` branches when a
// request is not sampled.
const NOOP_SPAN = { setAttribute: (): void => {}, recordError: (): void => {}, end: (): void => {} };

// Instrumentation must never be the reason a request fails: a logger that
// throws, or a registry at its cardinality limit, would otherwise turn into a
// 500 caused by the code meant to report 500s.
function safely(fn: () => void): void {
  try {
    fn();
  } catch {
    /* observability failures are swallowed on purpose */
  }
}

export async function instrument<T>(
  handler: () => Promise<T>,
  request: RequestLike,
  deps: Deps,
): Promise<{ result?: T; status: number; error?: Error }> {
  const header = request.headers["traceparent"];
  const match = header ? TRACEPARENT.exec(header.trim()) : null;
  const inbound =
    match && match[1] !== "ff" && !ALL_ZERO.test(match[2]) && !ALL_ZERO.test(match[3])
      ? { traceId: match[2], sampled: (Number.parseInt(match[4], 16) & 1) === 1 }
      : undefined;

  const traceId = inbound?.traceId ?? deps.nextId().padEnd(32, "0").slice(0, 32);
  const requestId = deps.nextId();
  const { sampled } = deps.sampler({ traceId, upstreamSampled: inbound?.sampled });
  const span = sampled ? deps.tracer.startSpan(`${request.method} ${request.route}`) : NOOP_SPAN;

  const started = deps.now();
  let status = 200;
  let failure: Error | undefined;
  let result: T | undefined;

  try {
    result = await deps.context.run({ requestId, traceId }, () => handler());
    safely(() => span.setAttribute("http.status_code", 200));
  } catch (error) {
    failure = error as Error;
    status = 500;
    safely(() => span.recordError(failure as Error));
  } finally {
    const durationMs = deps.now() - started;
    safely(() => span.end());

    const fields = {
      requestId,
      traceId,
      route: request.route,
      method: request.method,
      status,
      durationMs,
    };
    safely(() =>
      failure
        ? deps.logger.error({ msg: "request failed", ...fields, errorName: failure.name })
        : deps.logger.info({ msg: "request completed", ...fields }),
    );

    // Both metrics on both paths: a latency histogram fed only by successes is
    // a graph that looks healthy during an outage.
    // Labels are route and status only - ids live in the log and the span,
    // because a label is a permanent time series.
    safely(() => deps.metrics.counter("http_requests_total", { route: request.route, status: String(status) }));
    // Prometheus convention is base units, so seconds rather than the
    // milliseconds the clock gives us.
    safely(() =>
      deps.metrics.observe("http_request_duration_seconds", durationMs / 1000, { route: request.route }),
    );
  }

  return failure ? { error: failure, status } : { result, status };
}

